-- APN-MED — Nefrológiai-urológiai kórképek.
--
-- Négy kórkép, az APN napi munkájához igazítva:
--   · húgyúti fertőzés — a leggyakoribb, és a leggyakrabban túlkezelt;
--   · vesekólika — a fájdalomcsillapítás választása itt nem mindegy;
--   · hyperkalaemia — tünetmentesen alakul ki, az első jel a ritmuszavar lehet;
--   · akut vizeletretenció — az ellátása nagyrészt ápolói feladat.
--
-- A krónikus vesebetegség és az akut vesekárosodás már szerepel a
-- betegségtárban, ezért itt nem ismétlődnek.
--
-- Előfeltétel: a 0075 lefutott (a szakterület egyesítése).

insert into public.diseases
  (slug, name, aliases, abbrev, specialty, score_ids, lab_ids, ekg_ids,
   guideline_kw, body, status, version, is_stub)
values
  ('hugyuti-fertozes', 'Húgyúti fertőzés', '{"cystitis","hólyaghurut","pyelonephritis","UTI"}', 'HÚF', 'Nefrológia-urológia', '{"news2","qsofa"}', '{"crp","wbc","krea","egfr"}', '{}', '{"húgyúti fertőzés","cystitis","pyelonephritis"}', '{"brief_what": "A húgyutak bakteriális fertőzése. Az alsó húgyutakra korlátozódó forma a hólyaghurut, a vesemedencére terjedő a vesemedence-gyulladás — a kettő súlyossága és kezelése eltér.", "brief_why": "Az egyik leggyakoribb fertőzés, és az egyik leggyakrabban túlkezelt. A tünetmentes bakteriuria antibiotikumos kezelése nem javítja a kimenetelt, viszont mellékhatást és rezisztenciát okoz — ez a klasszikus antibiotikum-gazdálkodási hiba.", "when": ["Gyakori, sürgető vizelési inger, égő érzés vizeléskor", "Szuprapubikus fájdalom vagy nyomásérzés", "Láz, hidegrázás, deréktáji fájdalom — felső húgyúti érintettség", "Idős betegnél hirtelen zavartság, esés, étvágytalanság", "Zavaros, szagos vizelet — önmagában nem elég a kórisméhez"], "examine": ["A tünetek elkülönítése: alsó húgyúti panasz önmagában, vagy láz és deréktáji fájdalom is", "Vese tájéki kopogtatási érzékenység", "Vitális paraméterek: láz, pulzus, vérnyomás — a szepszis irányába", "Hólyagtelődés vizsgálata, ha retenció is felmerül", "Kockázati tényezők: terhesség, cukorbetegség, katéter, kőbetegség, közelmúltbeli urológiai beavatkozás", "Idős betegnél a zavartság mértéke és annak változása"], "labs": "A vizelet gyorsteszt és üledék tájékoztat, de a tünetek nélküli pozitív eredmény nem jelent kezelendő fertőzést. A tenyésztés a kezelés megkezdése előtt veendő. Lázas betegnél vérkép, CRP és vesefunkció is indokolt; szepszis gyanújánál hemokultúra.", "ekg": "Nem a kórkép része; szeptikus állapotban a monitorozás része.", "imaging": "Szövődménymentes hólyaghurutnál nem szükséges. Ismétlődő fertőzésnél, kezelésre nem javuló lázas állapotnál vagy kőgyanúnál ultrahang, esetleg CT.", "scores": "A NEWS2 az állapotromlás követésére, a qSOFA a szepszis felismerésére alkalmas. Külön súlyossági pontozó nincs.", "red_flags": ["Láz, hidegrázás, deréktáji fájdalom — a vesemedencére terjedt a fertőzés", "Vérnyomásesés, szapora pulzus, zavartság — szepszis", "Terhesség — itt a tünetmentes bakteriuria is kezelendő", "Vizeletürítés hiánya lázas beteg mellett — elzáródás gyanúja, sürgős urológiai ellátás", "Cukorbeteg vagy immunhiányos beteg lázas húgyúti fertőzése", "Ismétlődő fertőzés férfinál — mindig kivizsgálandó"], "apn_focus": ["A tünetmentes bakteriuria felismerése: pozitív vizelet tünetek nélkül nem kezelendő — kivéve terhességben és urológiai beavatkozás előtt", "Idős betegnél a zavartság gyakran az egyetlen jel, de a fordítottja is igaz: a zavartság nem mindig húgyúti fertőzés, és a kapkodó antibiotikum elfedheti a valódi okot", "A mintavétel a kezelés megkezdése előtt, tiszta módszerrel", "A katéteres beteg vizelete szinte mindig tartalmaz baktériumot; kezelés csak tünetek esetén", "Folyadékbevitel támogatása és a vizeletürítés követése", "A beteg oktatása: mit tegyen ismétlődés esetén, mikor kell orvoshoz fordulni"], "treatment": ["Szövődménymentes hólyaghurut: rövid antibiotikum-kúra, szűk spektrumú szerrel — nitrofurantoin vagy fosfomycin az elsődleges, nem fluorokinolon", "Vesemedence-gyulladás: hosszabb kezelés, súlyos esetben vénásan kezdve", "A tenyésztés eredménye alapján szűkíteni kell", "Fájdalomcsillapítás és folyadékpótlás minden esetben", "Elzáródás esetén a vizelet elvezetése az antibiotikum mellett elengedhetetlen"], "followup": ["Szövődménymentes esetben kontroll-tenyésztés nem szükséges, ha a tünetek megszűntek", "Ismétlődő fertőzésnél a kiváltó ok keresése: kő, elzáródás, hólyagürítési zavar", "Terhességben kontroll-tenyésztés szükséges", "Férfinál és gyermeknél urológiai kivizsgálás"], "source_name": "Hazai és nemzetközi húgyúti fertőzés-ajánlások, valamint a KDIGO 2024 CKD-irányelv vonatkozó szakaszai", "source_url": "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "version": "2024", "updated": "2026-09-14", "evidence": "A tünetmentes bakteriuria kezelésének elhagyása erős ajánlás, terhesség és urológiai beavatkozás kivételével. A szűk spektrumú szerek elsődlegessége szövődménymentes esetben szintén megalapozott."}'::jsonb, 'published', '1', false),
  ('vesekolika', 'Vesekólika és húgyúti kőbetegség', '{"vesekő","húgykő","urolithiasis","kólika"}', 'Vesekólika', 'Nefrológia-urológia', '{"news2"}', '{"krea","egfr","crp","wbc"}', '{}', '{"vesekő","kólika","urolithiasis"}', '{"brief_what": "A húgyúti kő elmozdulása okozta hirtelen, görcsös fájdalom. A kő elzárja a húgyvezetéket, a vesemedence megfeszül, és ez adja a jellegzetes hullámzó fájdalmat.", "brief_why": "Az egyik legerősebb fájdalommal járó kórkép, és a fájdalomcsillapítás választása nem mindegy: a gyulladáscsökkentők itt hatékonyabbak az opioidoknál. A lázzal együtt járó elzáródás viszont sürgősségi állapot.", "when": ["Hirtelen kezdődő, hullámzó erősségű ágyéki fájdalom", "A fájdalom a lágyék vagy a nemi szervek felé sugárzik", "Nyugtalanság: a beteg nem talál kényelmes testhelyzetet", "Hányinger, hányás", "Véres vizelet — nem mindig látható szabad szemmel"], "examine": ["A fájdalom jellege és kisugárzása", "Vese tájéki kopogtatási érzékenység", "Vitális paraméterek: a láz elzáródással együtt sürgősségi jel", "A vizeletürítés mennyisége és jellege", "Hasi vizsgálat: a hasi aortatágulat és más hasi katasztrófa hasonló fájdalmat adhat, különösen idős betegnél"], "labs": "Vizeletüledék a vérvizelés igazolására. Vesefunkció a szűrés megítéléséhez, különösen egyetlen vese vagy kétoldali kő esetén. Vérkép és CRP, ha fertőzés is felmerül.", "ekg": "Nem a kórkép része.", "imaging": "A natív hasi CT adja a legpontosabb képet. Terhességben és fiatal betegnél az ultrahang az első választás, sugárterhelés nélkül.", "scores": "Külön pontozó nincs. A NEWS2 a fertőzéssel szövődött eset követésére alkalmas.", "red_flags": ["Láz elzáródás mellett — fertőzött, elzárt húgyút: sürgős vizeletelvezetés szükséges, az antibiotikum önmagában nem elég", "Vizeletürítés hiánya — kétoldali elzáródás vagy egyetlen vese érintettsége", "Vesefunkció romlása", "Ötven év felett először jelentkező kólika — a hasi aortatágulat szakadása megtévesztően hasonló képet ad, és halálos", "Terhesség", "Kezelhetetlen fájdalom vagy folyamatos hányás"], "apn_focus": ["A fájdalomcsillapítás gyors megkezdése: a gyulladáscsökkentők itt hatékonyabbak az opioidoknál, mert a vesemedence nyomását is csökkentik", "A vesefunkció ismerete a gyulladáscsökkentő adása előtt — elzáródás mellett a vese érzékenyebb", "A láz jelzése: az elzárt, fertőzött húgyút sürgősségi állapot", "A vizelet szűrése a kő felfogására, ha az összetétel vizsgálata felmerül", "Folyadékbevitel: a túlzott itatás nem gyorsítja a kő távozását, viszont fokozhatja a fájdalmat", "A beteg tájékoztatása: a kő távozása napokig tarthat, és a fájdalom hullámokban tér vissza"], "treatment": ["Fájdalomcsillapítás: gyulladáscsökkentő az első választás, ha a vesefunkció engedi; metamizol görcsoldó hatása miatt szintén alkalmas", "Hányinger csillapítása", "Kis kő esetén várakozás, a spontán távozás esélyével", "Fertőzött elzáródásnál sürgős vizeletelvezetés — ez életmentő beavatkozás", "Nagyobb kő vagy tartós elzáródás esetén urológiai beavatkozás"], "followup": ["A kő összetételének vizsgálata ismétlődés esetén", "Anyagcsere-kivizsgálás visszatérő kőképződésnél", "Folyadékbevitel növelése a megelőzéshez — ez a leghatékonyabb egyszerű lépés", "Étrendi tanácsadás a kő típusa szerint"], "source_name": "Európai urológiai társaság kőbetegség-irányelve", "source_url": "https://uroweb.org/guidelines", "version": "2025", "updated": "2026-09-14", "evidence": "A gyulladáscsökkentők elsődlegessége a kólika fájdalmának csillapításában jól alátámasztott. A fertőzött elzáródás sürgős elvezetése erős ajánlás."}'::jsonb, 'published', '1', false),
  ('hyperkalaemia', 'Hyperkalaemia', '{"magas káliumszint","kálium-emelkedés"}', 'Hyperkalaemia', 'Nefrológia-urológia', '{"news2"}', '{"k","krea","egfr","na"}', '{"hyperk"}', '{"hyperkalaemia","kálium","elektrolit"}', '{"brief_what": "A vér káliumszintjének kóros emelkedése. A kálium a szívizom ingerelhetőségét szabályozza, ezért a magas szint életveszélyes ritmuszavarhoz vezethet.", "brief_why": "A vesebetegség leggyakoribb életveszélyes szövődménye, és tünetmentesen alakul ki: az első jel gyakran már a ritmuszavar. A kockázatot a gyakran együtt szedett gyógyszerek — ACE-gátló, kálium-megtakarító vízhajtó, gyulladáscsökkentő — együttesen sokszorozzák meg.", "when": ["Rutinszerű laborellenőrzés vesebetegnél", "ACE-gátló, szartán vagy kálium-megtakarító vízhajtó indítása vagy adagemelése után", "Akut vesekárosodás", "Izomgyengeség, zsibbadás, szívdobogásérzés", "EKG-n magas, csúcsos T-hullám"], "examine": ["A tünetek gyakran hiányoznak — ez a kórkép legveszélyesebb sajátossága", "Izomerő vizsgálata: a gyengeség a végtagokon kezdődik", "Szívritmus és pulzus", "Vizeletmennyiség — a csökkenés a vese érintettségére utal", "A teljes gyógyszerlista átnézése: ACE-gátló, szartán, spironolakton, gyulladáscsökkentő, kálium-kiegészítő, diétás sópótló"], "labs": "Szérumkálium, vesefunkció, nátrium és sav-bázis állapot. Fontos a mintavételi hiba kizárása: a szoros leszorítás, az ökölszorítás és a késleltetett feldolgozás hamisan magas értéket ad — ilyenkor ismételt mintavétel indokolt, de a klinikai kép alapján a kezelés nem halasztható.", "ekg": "Magas, csúcsos, keskeny alapú T-hullám a legkorábbi jel. Előrehaladva a P-hullám ellaposodik, a PR megnyúlik, a QRS kiszélesedik, végül sinushullám alakú kép jelenik meg. Az EKG-eltérés súlyossága nem mindig arányos a káliumszinttel — a kettőt együtt kell értékelni.", "imaging": "Nincs szerepe.", "scores": "Külön pontozó nincs. A NEWS2 az állapotromlás követésére alkalmas.", "red_flags": ["EKG-eltérés bármely formája — a kezelés nem várhat a laboreredmény megismétlésére", "Széles QRS vagy sinushullám alakú kép — közvetlen életveszély", "Izomgyengeség, bénulás", "Vizeletürítés hiánya", "Akut vesekárosodás mellett emelkedő kálium", "Több káliumemelő gyógyszer együttes szedése"], "apn_focus": ["A tünetmentesség a legfontosabb tudnivaló: a beteg jól érezheti magát a ritmuszavar kialakulásáig", "EKG készítése minden jelentősen emelkedett káliumszintnél — az eltérés jelenléte dönti el, mennyire sürgős a helyzet", "A gyógyszerlista célzott átnézése: a diétás sópótlók káliumot tartalmaznak, amit a betegek nem tudnak", "A mintavétel technikája számít: a szoros leszorítás hamisan magas értéket ad", "Kálium-ellenőrzés ACE-gátló vagy spironolakton indítása után egy héttel", "A betegoktatás a káliumban gazdag ételekről, ha tartós a kockázat"], "treatment": ["EKG-eltérés esetén a szívizom védelme az első lépés — ez nem csökkenti a káliumszintet, de megelőzi a ritmuszavart", "A kálium sejtbe juttatása inzulinnal és cukorral, illetve inhalációs béta-izgatóval — gyors, de átmeneti hatás", "A kálium eltávolítása: vízhajtó, kötőgyanta, súlyos esetben vesepótló kezelés", "A kiváltó gyógyszerek leállítása vagy adagcsökkentése", "A kálium ismételt ellenőrzése a kezelés után: a sejtbe juttatás átmeneti, a szint visszaemelkedhet"], "followup": ["Kálium-ellenőrzés a kiváltó ok rendezése után", "A gyógyszeres kezelés felülvizsgálata — a káliumemelő szerek elhagyása nem mindig indokolt, mert a szívvédő hatásuk is elveszne", "Étrendi tanácsadás tartós kockázat esetén", "Vesefunkció rendszeres követése"], "source_name": "KDIGO 2024 CKD-irányelv és hazai elektrolitzavar-ajánlások", "source_url": "https://kdigo.org/guidelines/ckd-evaluation-and-management/", "version": "2024", "updated": "2026-09-14", "evidence": "Az EKG-eltérés melletti azonnali szívizom-védelem erős ajánlás. A káliumemelő gyógyszerek automatikus elhagyása viszont nem javasolt: azok szív- és vesevédő hatása is mérlegelendő."}'::jsonb, 'published', '1', false),
  ('vizeletretencio', 'Akut vizeletretenció', '{"vizeletelakadás","húgyhólyag-retenció"}', 'Retenció', 'Nefrológia-urológia', '{"news2"}', '{"krea","egfr","k"}', '{}', '{"vizeletretenció","katéterezés","prosztata"}', '{"brief_what": "A hólyag kiürítésének hirtelen képtelensége, telt hólyag mellett. Fájdalmas állapot, amely a vesét is veszélyezteti, ha elhúzódik.", "brief_why": "Gyakori, és az ellátása nagyrészt ápolói feladat: a felismerés, a hólyagtelődés megítélése és a katéterezés. A leggyakoribb ok a prosztata-túltengés, de a gyógyszerek okozta forma gyakran elkerüli a figyelmet.", "when": ["Vizelési képtelenség telt hólyag mellett", "Alhasi fájdalom és feszülés", "Nyugtalanság, kínzó vizelési inger eredmény nélkül", "Idős betegnél zavartság vagy hirtelen állapotromlás", "Kis mennyiségű, csöpögő vizeletürítés — túlfolyásos inkontinencia"], "examine": ["Alhasi tapintás és kopogtatás: a telt hólyag tompulatot ad", "Hólyagtérfogat mérése ultrahanggal, ha elérhető — ez a legmegbízhatóbb", "A gyógyszerlista átnézése: vizelettartást okozó szerek", "Székrekedés keresése: a telt végbél gyakori, könnyen orvosolható kiváltó ok", "Neurológiai jelek: alsó végtagi gyengeség, nyeregtáji érzéskiesés", "Férfinál prosztata megítélése"], "labs": "Vesefunkció és kálium: az elhúzódó elzáródás akut vesekárosodást okoz. Vizeletvizsgálat fertőzés irányában.", "ekg": "Nem a kórkép része; magas káliumszint gyanújánál indokolt.", "imaging": "Hólyag-ultrahang a térfogat megítélésére. Vese-ultrahang, ha a vesefunkció romlott — a felső húgyutak tágulata elzáródásra utal.", "scores": "Külön pontozó nincs.", "red_flags": ["Alsó végtagi gyengeség, nyeregtáji érzéskiesés, székletinkontinencia — gerincvelői érintettség, azonnali képalkotás és idegsebészeti konzultáció", "Láz — fertőzött elzáródás", "Vesefunkció romlása vagy magas káliumszint", "Kétoldali vesetágulat képalkotón", "Katéterezés sikertelensége — urológiai segítség szükséges, az erőltetés sérülést okoz"], "apn_focus": ["A hólyagtérfogat mérése ultrahanggal megbízhatóbb, mint a tapintás — és megelőzi a fölösleges katéterezést", "A gyógyszerlista átnézése: vizelettartást okozhat több gyakori szer, köztük egyes hidegrázás elleni és allergia elleni készítmények, valamint a görcsoldók és egyes antidepresszánsok", "A székrekedés kizárása: a telt végbél gyakori és könnyen orvosolható ok", "Katéterezés után a leürített mennyiség mérése és dokumentálása", "Nagy mennyiség leürítése után a vérnyomás és a vizeletmennyiség követése: az elzáródás megszűnése után átmeneti fokozott vizeletürítés léphet fel", "A katéter szükségességének rendszeres felülvizsgálata — a fölösleges katéter fertőzésforrás"], "treatment": ["A hólyag leürítése katéterrel — ez szünteti meg a fájdalmat és védi a vesét", "A kiváltó ok kezelése: gyógyszer elhagyása, székrekedés rendezése, fertőzés kezelése", "Prosztata-túltengésnél gyógyszeres kezelés indítása a katéter eltávolítása előtt", "Sikertelen katéterezésnél urológiai segítség; az erőltetés húgycsősérülést okoz"], "followup": ["A katéter eltávolításának megkísérlése a kiváltó ok rendezése után", "A vizeletürítés sikerének ellenőrzése a katéter eltávolítása után", "Urológiai kivizsgálás ismétlődő retenciónál", "Vesefunkció ellenőrzése, ha az elzáródás elhúzódott"], "source_name": "Európai urológiai társaság ajánlásai a húgyúti elzáródásról és a jóindulatú prosztata-megnagyobbodásról", "source_url": "https://uroweb.org/guidelines", "version": "2025", "updated": "2026-09-14", "evidence": "A hólyagtérfogat ultrahangos mérése megbízhatóbb a fizikális vizsgálatnál, és csökkenti a fölösleges katéterezések számát. A gerincvelői érintettség kizárása minden akut retenciónál indokolt."}'::jsonb, 'published', '1', false)
