-- ══ Ellenőrzés ═══════════════════════════════════════════
-- A szakterület teljes tartalma. Hat kórképnek kell megjelennie:
-- a két korábbinak és a négy újnak.
select slug, name, status, is_stub,
  case when body ->> 'brief_what' is null then 'csonk' else 'kidolgozott' end as allapot
from public.diseases
where specialty = 'Nefrológia-urológia'
order by name;
